const TRANSITIONS=Object.freeze({DRAFT:['SHADOW','RETIRED'],SHADOW:['CANARY','ROLLBACK','RETIRED'],CANARY:['ACTIVE','ROLLBACK','RETIRED'],ACTIVE:['ROLLBACK','RETIRED'],ROLLBACK:['SHADOW','RETIRED'],RETIRED:[]});
export class IntelligenceModelRegistry {#models=new Map();register(input={}){if(!input.modelId||!input.version)throw new TypeError('modelId/version required');const key=`${input.modelId}@${input.version}`;if(this.#models.has(key))throw new Error('model already exists');const row={...structuredClone(input),key,state:'DRAFT',metrics:null,evidence:[]};this.#models.set(key,row);return structuredClone(row);}attachMetrics(key,metrics){const m=this.#models.get(key);if(!m)throw new Error('unknown model');m.metrics=structuredClone(metrics);return structuredClone(m);}attachEvidence(key,evidence){const m=this.#models.get(key);if(!m)throw new Error('unknown model');m.evidence.push(structuredClone(evidence));return structuredClone(m);}transition(key,next,{gate=()=>false}={}){const m=this.#models.get(key);if(!m)throw new Error('unknown model');if(!TRANSITIONS[m.state].includes(next))throw new Error(`invalid transition ${m.state}->${next}`);if((next==='CANARY'||next==='ACTIVE')&&!gate(structuredClone(m)))throw new Error('release gate denied');m.state=next;return structuredClone(m);}get(key){const m=this.#models.get(key);return m?structuredClone(m):null;}snapshot(){return[...this.#models.values()].map(structuredClone);}}
